<script setup lang="ts">
import { computed, onMounted, onUnmounted, reactive, ref } from 'vue';
import { useRoute, useRouter } from 'vue-router';
import { DataAnalysis, User, UserFilled, Headset, DocumentAdd, FolderOpened, Tickets, TrendCharts, Setting, Key, ArrowRight, ArrowDown, Bell, Plus, SwitchButton, Lock, Refresh, Fold, Expand } from '@element-plus/icons-vue';
import { ElMessage } from 'element-plus';
import { api, notifyError } from './lib/api';
import { authenticated, state, refresh } from './lib/store';
import { requestEditorLeave } from './lib/leaveGuard';
const route=useRoute(),router=useRouter();
const ready=ref(false),busy=ref(false),collapsed=ref(false),changePassword=ref(false);
const login=reactive({username:'admin',password:''});
const password=reactive({oldPassword:'',newPassword:'',confirm:''});
const menus=[{path:'/dashboard',name:'工作台',icon:DataAnalysis},{path:'/customers',name:'客户与会员',icon:User},{path:'/players',name:'陪玩成员',icon:Headset},{path:'/quotes',name:'开单报价',icon:DocumentAdd},{path:'/quote-drafts',name:'开单草稿',icon:FolderOpened},{path:'/orders',name:'订单与派单',icon:Tickets},{path:'/reports',name:'数据报表',icon:TrendCharts},{path:'/management',name:'账号与审计',icon:Key,admin:true},{path:'/settings',name:'规则与设置',icon:Setting,admin:true}];
const visibleMenus=computed(()=>menus.filter(m=>!m.admin||state.user.role==='admin'));
const current=computed(()=>menus.find(m=>m.path===route.path)?.name||'工作台');
const today=computed(()=>new Date().toLocaleDateString('zh-CN',{timeZone:'Asia/Shanghai',year:'numeric',month:'long',day:'numeric',weekday:'long'}));
let timer:ReturnType<typeof setInterval>;
async function signIn(){if(!login.username||!login.password)return ElMessage.warning('请输入账号和密码');busy.value=true;try{await api('/api/login',{method:'POST',body:JSON.stringify(login)});await refresh();await router.replace('/dashboard');if(state.user.mustChangePassword)changePassword.value=true;}catch(e){notifyError(e);}finally{busy.value=false;}}
async function logout(){if(!await requestEditorLeave('logout'))return;try{await api('/api/logout',{method:'POST'});}catch{}authenticated.value=false;login.password='';}
async function savePassword(){if(password.newPassword!==password.confirm)return ElMessage.warning('两次输入的密码不一致');busy.value=true;try{await api('/api/password',{method:'POST',body:JSON.stringify(password)});changePassword.value=false;Object.assign(password,{oldPassword:'',newPassword:'',confirm:''});ElMessage.success('密码已更新');await refresh();}catch(e){notifyError(e);}finally{busy.value=false;}}
function expired(){authenticated.value=false;}
async function reload(){try{await refresh();ElMessage.success('数据已更新');}catch(e){notifyError(e);}}
onMounted(async()=>{window.addEventListener('auth:expired',expired);try{await refresh();}catch{}finally{ready.value=true;}timer=setInterval(()=>{if(authenticated.value)refresh().catch(()=>{});},30000);});
onUnmounted(()=>{window.removeEventListener('auth:expired',expired);clearInterval(timer);});
</script>
<template>
  <div v-if="!ready" class="app-loading"><div class="brand-icon">B</div><p>正在载入贝蒂工作台…</p></div>
  <div v-else-if="!authenticated" class="login-page">
    <section class="login-story"><div class="login-brand"><div class="brand-icon">B<span>✦</span></div><div><strong>Batty Club</strong><span>贝蒂电竞俱乐部</span></div></div><div class="story-copy"><span class="eyebrow">GOOD SERVICE, GREAT COMPANY</span><h1>每一份陪伴，<br/>都安排妥当。</h1><p>从第一次问候，到每一笔订单。<br/>在一个工作台，让客户、陪玩与服务紧密相连。</p><div class="story-chips"><span>客户与会员</span><span>清晰报价</span><span>高效派单</span></div></div><div class="story-art"><div class="art-orbit"></div><div class="art-card main"><span class="art-label">一切就绪，准备开场</span><div class="art-avatars"><i>糖</i><i>北</i><i>星</i></div><b>让每一次组队<br/>都成为好体验。</b><div class="art-progress"><span></span></div><small>服务连接中 <span>✦</span></small></div><div class="art-card mini"><i>✓</i><span>新订单已安排<strong>陪伴，从此刻开始</strong></span></div><span class="art-star one">✦</span><span class="art-star two">✧</span></div><footer>Batty Club Operations Console · 本地试用版</footer></section>
    <section class="login-form-area"><div class="login-form"><span class="login-welcome">欢迎回来</span><h2>登录你的工作台</h2><p class="muted">使用管理员分配的账号，开始今天的工作。</p><el-form @submit.prevent="signIn" label-position="top" size="large"><el-form-item label="登录账号"><el-input v-model="login.username" autocomplete="username" placeholder="输入账号" :prefix-icon="User" /></el-form-item><el-form-item label="登录密码"><el-input v-model="login.password" type="password" autocomplete="current-password" show-password placeholder="输入密码" :prefix-icon="Lock" @keyup.enter="signIn" /></el-form-item><el-button type="primary" native-type="submit" :loading="busy" class="login-submit">登 录<el-icon><ArrowRight/></el-icon></el-button></el-form><div class="demo-accounts"><span>本地体验账号</span><button @click="login.username='admin';login.password='Batty2026!'">管理员 <b>admin</b><small>Batty2026!</small></button><button @click="login.username='kefu';login.password='Staff2026!'">客服 <b>kefu</b><small>Staff2026!</small></button></div><p class="login-note">系统仅计算与记账，收付款由客服在线下核实。</p></div></section>
  </div>
  <div v-else class="app-shell" :class="{collapsed}">
    <aside class="sidebar"><router-link to="/dashboard" class="sidebar-brand"><div class="brand-icon">B<span>✦</span></div><div v-if="!collapsed"><strong>Batty Club</strong><span>贝蒂电竞 · 运营工作台</span></div></router-link><div class="nav-section" v-if="!collapsed">日常工作</div><nav><router-link v-for="item in visibleMenus" :key="item.path" :to="item.path" :class="{active:route.path===item.path}" :title="item.name"><el-icon><component :is="item.icon"/></el-icon><span v-if="!collapsed">{{item.name}}</span><span v-if="!collapsed&&item.path==='/orders'&&state.dashboard.pendingDispatch" class="nav-count">{{state.dashboard.pendingDispatch}}</span></router-link></nav><div class="sidebar-bottom"><div v-if="!collapsed" class="sidebar-tip"><span>✦</span><b>把服务安排得更好</b><small>确认清楚，记录完整，陪伴到位。</small></div><div class="local-status"><i></i><span v-if="!collapsed">本地服务 · V0.1</span></div></div></aside>
    <main class="app-main"><header class="topbar"><div class="breadcrumbs"><button class="icon-button" :aria-label="collapsed?'展开菜单':'折叠菜单'" @click="collapsed=!collapsed"><el-icon><component :is="collapsed?Expand:Fold"/></el-icon></button><span>运营管理</span><el-icon class="crumb-arrow"><ArrowRight/></el-icon><strong>{{current}}</strong></div><div class="topbar-actions"><span class="today">{{today}}</span><el-tooltip content="刷新数据"><button class="icon-button" aria-label="刷新数据" @click="reload"><el-icon><Refresh/></el-icon></button></el-tooltip><el-tooltip content="查看待处理订单"><button class="icon-button notification" aria-label="待处理订单" @click="router.push('/orders')"><el-icon><Bell/></el-icon><span v-if="state.dashboard.pendingDispatch||state.dashboard.pendingPayment" class="notification-dot" aria-hidden="true"></span></button></el-tooltip><div class="topbar-divider"></div><el-dropdown trigger="click"><button type="button" class="user-menu" aria-label="账号菜单" :title="state.user.name"><div class="user-avatar"><el-icon :size="18"><UserFilled/></el-icon></div><div class="user-info"><b>{{state.user.name}}</b><span>{{state.user.role==='admin'?'管理员':'客服'}}</span></div><el-icon class="account-chevron"><ArrowDown/></el-icon></button><template #dropdown><el-dropdown-menu><el-dropdown-item @click="changePassword=true"><el-icon><Lock/></el-icon>修改密码</el-dropdown-item><el-dropdown-item divided @click="logout"><el-icon><SwitchButton/></el-icon>退出登录</el-dropdown-item></el-dropdown-menu></template></el-dropdown></div></header><div class="content"><router-view/></div><footer class="app-footer"><span>Batty Club · 用心安排每一份陪伴</span><span>本地试用版 V0.1</span></footer></main>
  </div>
  <el-dialog v-model="changePassword" title="修改登录密码" width="440px" :close-on-click-modal="false"><el-form label-position="top"><el-form-item label="当前密码"><el-input type="password" v-model="password.oldPassword" show-password/></el-form-item><el-form-item label="新密码（至少10位，含字母与数字）"><el-input type="password" v-model="password.newPassword" show-password/></el-form-item><el-form-item label="再次输入新密码"><el-input type="password" v-model="password.confirm" show-password/></el-form-item></el-form><template #footer><el-button @click="changePassword=false">取消</el-button><el-button type="primary" :loading="busy" @click="savePassword">更新密码</el-button></template></el-dialog>
</template>
